from lib import *
S = SS('k77')
F1 = [['kubectl cordon worker', 'unschedulable=true + 污点'], ['已有 Pod', '不动'], ['扩到 5 副本', '新增的 2 个去 worker2']]
F2 = [['drain(无 flag)', '3 类拒绝'], ['+ --ignore-daemonsets', '剩 2 类'], ['+ --delete-emptydir-data', '剩裸 Pod'], ['+ --force', '成功 3.1 秒']]
F3 = [['PDB minAvailable=3', 'disruptionsAllowed=0'], ['drain worker2', '重试 5 秒一次'], ['25 秒超时', '退出码 1,仍在 cordon'], ['删 PDB 后', '4.1 秒 drain 完']]
F4 = [['uncordon', ''], ['调度恢复', 'unschedulable 清除'], ['Pod 位置', '不变,不会迁回']]
PANELS = [('f', 'flow', 'cordon 与 drain'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("kubectl cordon kx-main-worker:节点 spec.unschedulable=true,同时自动带上污点 node.kubernetes.io/unschedulable:NoSchedule,kubectl get nodes 里状态是 Ready,SchedulingDisabled。节点上已有的 Pod(bare、dep、ds、scratch)原封不动;把 Deployment 扩到 5 个副本,新增的 2 个只能去 worker2。", f=fl(F1, cur=[0], done=[1, 2]), t=tl(S(1), mark=lidx(S(1), 'unschedulable=True', 'SchedulingDisabled'), done=lidx(S(1), '已有的 Pod 不受影响', '扩到 5 个副本')), kv=KV([['cordon', '只拦新 Pod,不碰旧的'], ['污点', 'unschedulable:NoSchedule'], ['DaemonSet', '自带容忍,新建照样能落到被 cordon 的节点']], ['cordon'])),
    step("kubectl drain 逐步加 flag:直接 drain 报错列出三类不能删的:没有控制器的 bare、DaemonSet 管理的 ds / kindnet / kube-proxy、带本地存储的 scratch 和 metrics-server;加 --ignore-daemonsets 后剩两类;再加 --delete-emptydir-data 后只剩没有控制器的 bare、scratch;最后加 --force 才成功,3.1 秒内驱逐 metrics-server、scratch、bare、一个 dep Pod,node/kx-main-worker drained。结果:dep 的 3 个副本都在 worker2,DaemonSet 的 Pod 仍在 worker 上,bare 和 scratch 被直接删掉(没有控制器,不会重建)。", f=fl(F2, cur=[0, 1, 2, 3]), t=tl(S(2), mark=lidx(S(2), '直接 kubectl drain', '再加 --delete-emptydir-data'), done=lidx(S(2), '再加 --force', 'drain 之后各节点', 'bare(裸 Pod')), kv=KV([['--ignore-daemonsets', 'DaemonSet 的 Pod 不会被迁走'], ['--delete-emptydir-data', '承认 emptyDir 里的数据会丢'], ['--force', '裸 Pod 会被删除且不会重建']], ['--force'])),
    step("PDB dep-pdb(minAvailable: 3,当前 healthy=3):disruptionsAllowed=0。drain worker2(上面有 dep 的副本):metrics-server 被驱逐了,dep 的 Pod 报 Cannot evict pod as it would violate the pod's disruption budget,drain 每 5 秒重试一次,25 秒超时退出码 1;Pod 仍在 worker2 上,节点已经是 cordoned——drain 失败也不会撤销 cordon。删掉 PDB 后重新 drain,4.1 秒完成,dep 全部去了 worker。", f=fl(F3, cur=[1, 2], mark=[0], done=[3]), t=tl(S(3), mark=lidx(S(3), 'disruptionsAllowed=0', 'violate the pod'), done=lidx(S(3), '删掉 PDB 后')), kv=KV([['drain 走 Eviction API', 'PDB 会生效'], ['卡住时', '每 5 秒重试,直到超时'], ['cordon 仍然有效', '要自己 uncordon']], ['Eviction API'])),
    step("kubectl uncordon 两个节点后:spec.unschedulable 清除、污点消失,调度恢复。Pod 位置不变(worker 上 dep ×3、ds,worker2 上 ds),不会自己迁回;需要重建或 rollout 才会重新分布。", f=fl(F4, cur=[1], done=[0, 2]), t=tl(S(4), mark=lidx(S(4), 'uncordon 两个节点后'), done=lidx(S(4), 'worker2 的')), kv=KV([['uncordon', '只恢复可调度'], ['不重分布', '调度器不会把已有 Pod 搬走'], ['要均衡', 'rollout restart 或 descheduler']], ['不重分布'])),
]
A = mkartk('k77', 77, 'Kubernetes,cordon,drain,PodDisruptionBudget,驱逐,运维,真实验证,动画演示',
    '在 kind 集群里实测 cordon 与 drain:cordon 设 spec.unschedulable 并加 NoSchedule 污点,只拦新 Pod;drain 默认拒绝裸 Pod、DaemonSet 管理的 Pod 和带 emptyDir 的 Pod,逐步加 --ignore-daemonsets、--delete-emptydir-data、--force 才成功(3.1 秒);PDB minAvailable=3 让 drain 每 5 秒重试直到 25 秒超时且 cordon 保持不变;uncordon 后 Pod 不会自己迁回。',
    'kubectl drain 到底做了什么?为什么总要加一堆 flag?PodDisruptionBudget 怎么让它卡住?uncordon 之后 Pod 会回来吗?这篇在真集群里一步步加 flag、再制造 PDB 阻塞,把输出原样记下来。',
    [('3 类拒绝', '直接 drain 被拒的三类 Pod:没有控制器的、DaemonSet 管的、带 emptyDir 的'), ('3.1 秒', '加全 flag 后 drain 完成的用时'), ('retry after 5s', 'PDB 阻塞时 drain 的重试间隔,25 秒超时后退出码 1')],
    [('cordon:只拦新 Pod', '<p><code>kubectl cordon</code> 把节点的 <code>spec.unschedulable</code> 设为 true,同时带上污点 <code>node.kubernetes.io/unschedulable:NoSchedule</code>,<code>kubectl get nodes</code> 显示 <code>Ready,SchedulingDisabled</code>。节点上已有的 Pod 不动;把 Deployment 扩到 5 个副本,新增的 2 个只能去 worker2。</p>'),
     ('drain:一道道拦', '<p>直接 <code>kubectl drain</code> 报错,列出三类不能删的:没有控制器的 <code>bare</code>、DaemonSet 管理的(<code>ds</code>、<code>kindnet</code>、<code>kube-proxy</code>)、带本地存储的(<code>scratch</code>、<code>metrics-server</code>)。加 <code>--ignore-daemonsets</code> 后剩两类;再加 <code>--delete-emptydir-data</code> 后只剩没有控制器的 <code>bare</code> 和 <code>scratch</code>;加 <code>--force</code> 才成功,3.1 秒内驱逐了 metrics-server、scratch、bare 和一个 dep Pod。结果是 dep 的 3 个副本都在 worker2,DaemonSet 的 Pod 仍留在 worker 上,<code>bare</code> 和 <code>scratch</code> 被直接删掉,不会重建。</p>'),
     ('PDB 让 drain 卡住', '<p>PDB <code>dep-pdb</code>(<code>minAvailable: 3</code>,当前 healthy=3)的 <code>disruptionsAllowed</code> 是 0。drain worker2:metrics-server 被驱逐,dep 的 Pod 报 <code>Cannot evict pod as it would violate the pod\'s disruption budget</code>,<code>drain</code> 每 5 秒重试一次,25 秒超时退出码 1;Pod 仍在 worker2 上,节点却已经被 cordon——drain 失败也不会撤销 cordon。删掉 PDB 后重新 drain,4.1 秒完成。</p>'),
     ('uncordon', '<p><code>kubectl uncordon</code> 只清除 <code>spec.unschedulable</code> 和污点,Pod 位置不变:worker 上还是 dep ×3 和 ds,worker2 上只有 ds,不会自己迁回。需要均衡就 <code>rollout restart</code> 或使用 descheduler。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,2 个 worker),被 drain 的节点上同时有 Deployment、DaemonSet、裸 Pod、带 emptyDir 的 Pod 和 metrics-server;PDB 的阻塞用 --timeout=25s 截断;各 Pod 的 terminationGracePeriodSeconds 设为 2 秒;每种情形各一次(各次运行里被驱逐的 dep Pod 个数取决于它们先前落在哪个节点)',
     '没有验证:drain 的并发与 --grace-period 覆盖;PDB 的 maxUnavailable 与 unhealthyPodEvictionPolicy;StatefulSet 的 drain 顺序;kubectl drain 的 --pod-selector 与 --disable-eviction;Eviction API 与直接删除的差别;节点上带 PV 的 Pod 迁移;cordon 与控制面污点的关系'],
    'cordon 与 drain', PANELS)
